{
  "results": [
    {
      "n": "G1",
      "evidence": "Screenshots 1 through 5 show the 3D scene rendering in Chrome with no blank screen or visible errors.",
      "pass": true
    },
    {
      "n": "G2",
      "evidence": "Screenshots 2 to 5 demonstrate camera orbiting and zooming, and OrbitControls in the code restricts maxPolarAngle to Math.PI * 0.465 and maxDistance to 15.5 so the camera cannot go below ground or beyond the 34x34 cloth.",
      "pass": true
    },
    {
      "n": "G3",
      "evidence": "The scene uses moderate procedural geometry counts, one instanced mesh, two shadow maps (2048 and 1024), and lightweight bloom and bokeh passes, which will comfortably run at 30 fps or more on a standard laptop.",
      "pass": true
    },
    {
      "n": "1",
      "evidence": "Screenshots 1 through 5 display an on-screen UI bar at the bottom with instructional text and interactive 'Macro DoF: ON' and 'Hero Angle' buttons.",
      "pass": false
    },
    {
      "n": "2",
      "evidence": "Inspecting the animate() loop in the HTML source shows only camera controls and depth-of-field focus updates, with no environmental motion running on load.",
      "pass": false
    },
    {
      "n": "3",
      "evidence": "Screenshot 1 frames the French toast stack close up, centered on the plate, and viewed from slightly above, matching the camera angle and framing of the reference photo.",
      "pass": true
    },
    {
      "n": "4",
      "evidence": "Screenshots 1, 2, 3, and 5 show three slices of French toast stacked on top of one another and rotationally offset like the reference photo.",
      "pass": true
    },
    {
      "n": "5",
      "evidence": "Screenshots 1 and 2 show banana slices wedged between the toast layers as well as placed on the plate to the left and leaning at the front base.",
      "pass": true
    },
    {
      "n": "6",
      "evidence": "Screenshots 1 and 4 show a cluster of blueberries on top of the stack and additional blueberries arranged around the base of the stack on the plate.",
      "pass": true
    },
    {
      "n": "7",
      "evidence": "Screenshots 1 and 5 show the toast stack sitting on a dark round plate resting on a grey-brown cloth surface.",
      "pass": true
    },
    {
      "n": "8",
      "evidence": "Screenshots 1 through 5 show white sugar particles scattered across the dark plate and finer specks dusted over the top of the toast and berries.",
      "pass": true
    },
    {
      "n": "9",
      "evidence": "In Screenshots 1 through 5, the toast slices have uniform sinusoidal fluting around all four sides and smooth plastic-like surfaces, reading like giant corrugated biscuits rather than cut bread slices.",
      "pass": false
    },
    {
      "n": "10",
      "evidence": "Screenshots 1 and 4 show the banana slices as round discs featuring a faint three-pointed seeded pattern in the center.",
      "pass": true
    },
    {
      "n": "11",
      "evidence": "In Screenshots 1 through 4, the blueberries are round, vary slightly in size, and display sculpted star-shaped crowns at their poles.",
      "pass": true
    },
    {
      "n": "12",
      "evidence": "Across Screenshots 1 through 5, all toast slices and fruit pieces make contact with the plate or each other, with no items floating in mid-air.",
      "pass": true
    },
    {
      "n": "13",
      "evidence": "In Screenshots 1, 2, 3, and 5, the finite cloth plane ends in a sharp horizontal edge across the upper background against a black void, and the plate shows a visible concentric crease ring.",
      "pass": false
    },
    {
      "n": "14",
      "evidence": "In the code, keyLight is placed in front-left (z = 5.4) rather than behind-left, and in Screenshot 1 the syrup drips and puddles look dark and dull without bright warm highlights.",
      "pass": false
    },
    {
      "n": "15",
      "evidence": "In Screenshot 1, the depth-of-field blur is very weak, leaving the back rim of the plate and the far edge of the cloth nearly crisp instead of softly blurred like the photo.",
      "pass": false
    },
    {
      "n": "16",
      "evidence": "In Screenshots 1 and 4, the blueberries on top of the toast and the banana slice on the left of the plate lack soft contact shadows to ground them.",
      "pass": false
    },
    {
      "n": "17",
      "evidence": "In Screenshot 1, the entire strip above the horizon edge of the cloth at the top of the frame is pure, featureless black.",
      "pass": false
    },
    {
      "n": "18",
      "evidence": "In Screenshot 1, the syrup rivulets on the crust appear dark brown and semi-matte, while the puddles on the plate look like flat, opaque brown patches lacking bright specular highlights.",
      "pass": false
    },
    {
      "n": "19",
      "evidence": "In Screenshots 1 through 4, the toast displays smooth, uniform vertex-color gradients from pale yellow centers to orange-brown edges with no porous bread crumb texture.",
      "pass": false
    },
    {
      "n": "20",
      "evidence": "In Screenshots 1 through 4, the blueberries have high-contrast blotchy white-and-blue marbling and a glossy sheen rather than a soft, dusty matte bloom.",
      "pass": false
    },
    {
      "n": "21",
      "evidence": "In Screenshots 1, 3, and 4, the banana slices look opaque and flat with dark grey shading artifacts along their rims rather than moist and slightly translucent.",
      "pass": false
    },
    {
      "n": "22",
      "evidence": "While the plate shows a dark ceramic sheen, the cloth in Screenshots 1 and 5 reads as a blurry mottled grey surface rather than clearly woven fabric.",
      "pass": false
    },
    {
      "n": "23",
      "evidence": "Screenshots 1 and 5 show that both the plate and the underlying cloth plane are horizontal and level with no unintended tilt.",
      "pass": true
    },
    {
      "n": "24",
      "evidence": "The syrup rivulets are static TubeGeometry meshes with no animation code in animate() to make them drip or run.",
      "pass": false
    },
    {
      "n": "25",
      "evidence": "Neither the screenshots nor the HTML source contain any steam or warm haze particles rising from the toast.",
      "pass": false
    },
    {
      "n": "26",
      "evidence": "Because no environmental motion is implemented in the scene, there is no looping motion at real-world speed.",
      "pass": false
    },
    {
      "n": "27",
      "evidence": "Each blueberry and banana slice in the code is generated with a distinct procedural deformation seed, radius, and 3D rotation, avoiding identical adjacent copies in Screenshots 1 and 4.",
      "pass": true
    },
    {
      "n": "28",
      "evidence": "Screenshots 1, 2, 3, and 4 show heavy geometry clipping: banana slices intersect deeply into the top toast slice and the plate, and in Screenshot 2 a blueberry pokes straight through the side crust of the middle toast.",
      "pass": false
    },
    {
      "n": "29",
      "evidence": "In Screenshots 1 through 5, the sugar on the plate appears as coarse, distinct white pellets and polka dots rather than a fine powdery dusting.",
      "pass": false
    },
    {
      "n": "30",
      "evidence": "Screenshot 1 is immediately recognizable as stylized 3D graphics due to the biscuit-fluted plastic toast, clipping grey-rimmed bananas, coarse white dots, black background void, and UI overlay.",
      "pass": false
    }
  ]
}
